=<div style="font-family: 'Segoe UI', Arial, sans-serif; color: #333; max-width: 1000px; margin: auto; line-height: 1.4;">

  <h2 style="color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; text-align: center;">Informe Consolidado de Gastos</h2>

  <h3 style="color: #7f8c8d; font-size: 14px; margin-top: 10px;">🛡️ 1. Logs de Validación y Auditoría</h3>
  <table style="border-collapse: collapse; width: 100%; font-size: 10px; margin-bottom: 25px; background-color: #fcfcfc; border: 1.5px solid #2c3e50;">
    <thead style="background-color: #f1f2f6; color: #57606f;">
      <tr>
        <th style="padding: 6px; text-align: left; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Producto Detectado</th>
        <th style="padding: 6px; text-align: center; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Categoría Asignada</th>
        <th style="padding: 6px; text-align: center; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Origen</th>
        <th style="padding: 6px; text-align: left; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Razonamiento / Validación</th>
      </tr>
    </thead>
    <tbody>
      {{
        $json.data.map((item, index) => {
          const catNueva = item.categoria || item.output?.categoria || "Otros";
          const origenRaw = item.origen || item.output?.origen || "Sistema";
          const esDirecta = origenRaw.includes("Directa");
          const prod = item.productos || item.output?.productos || "N/A";
          const razon = item.razonamiento || item.output?.razonamiento || "Validación automática";
          const color = esDirecta ? "#27ae60" : "#2980b9";
          const bgColor = index % 2 === 0 ? "#ffffff" : "#f9fbfd";

          return `
          <tr style="background-color: ${bgColor};">
            <td style="padding: 5px; font-weight: bold; border: 1.5px solid #2c3e50;">${prod}</td>
            <td style="padding: 5px; text-align: center; border: 1.5px solid #2c3e50; font-weight: bold;">${catNueva}</td>
            <td style="padding: 5px; text-align: center; color: ${color}; font-weight: bold; border: 1.5px solid #2c3e50;">${origenRaw}</td>
            <td style="padding: 5px; font-style: italic; color: #666; border: 1.5px solid #2c3e50;">${razon}</td>
          </tr>`;
        }).join('')
      }}
    </tbody>
  </table>

  <h3 style="color: #2c3e50; font-size: 15px;">💰 2. Detalle Consolidado para Registro</h3>
  <table style="border-collapse: collapse; width: 100%; font-size: 11px; border: 1.5px solid #2c3e50;">
    <thead style="background-color: #34495e; color: white;">
      <tr>
        <th style="padding: 10px; text-align: center; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Fecha</th>
        <th style="padding: 10px; text-align: left; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Descripción (Keywords)</th>
        <th style="padding: 10px; text-align: left; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Categoría Final</th>
        <th style="padding: 10px; text-align: right; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Valor Total</th>
        <th style="padding: 10px; text-align: center; border: 1.5px solid #2c3e50; border-bottom: 2.5px solid #2c3e50;">Método</th>
      </tr>
    </thead>
    <tbody>
      {{
        Object.values($json.data.reduce((acc, item) => {
          const cat = item.categoria || item.output?.categoria || "Sin Clasificar";
          const val = Number(item.valor_categoria || item.output?.valor_categoria || 0);
          const rawProd = item.productos || item.output?.productos || "";
          const firstWords = rawProd.split(',').map(p => p.trim().split(' ')[0]).filter(p => p);

          if (!acc[cat]) {
            acc[cat] = { 
                fecha: item.fecha || item.output?.fecha || 'N/A', 
                tienda: item.tienda || item.output?.tienda || 'Tienda',
                keywords: new Set(),
                categoria: cat, 
                total: 0, 
                metodo: item.metodo_pago || item.output?.metodo_pago || 'N/A' 
            };
          }
          acc[cat].total += val;
          firstWords.forEach(w => acc[cat].keywords.add(w));
          return acc;
        }, {})).sort((a, b) => b.total - a.total).map((g, index) => {
          const descripcionFinal = `${g.tienda} (${Array.from(g.keywords).join(', ')})`;
          const bgColor = index % 2 === 0 ? "#ffffff" : "#f9fbfd";

          return `
          <tr style="background-color: ${bgColor};">
            <td style="padding: 8px; text-align: center; border: 1.5px solid #2c3e50;">${g.fecha}</td>
            <td style="padding: 8px; border: 1.5px solid #2c3e50;">${descripcionFinal}</td>
            <td style="padding: 8px; border: 1.5px solid #2c3e50;"><b>${g.categoria}</b></td>
            <td style="padding: 8px; text-align: right; font-weight: bold; border: 1.5px solid #2c3e50;">$ ${g.total.toLocaleString()}</td>
            <td style="padding: 8px; text-align: center; border: 1.5px solid #2c3e50;">${g.metodo}</td>
          </tr>`;
        }).join('')
      }}
    </tbody>
    <tfoot style="background-color: #f8f9fa; font-weight: bold;">
      <tr style="font-size: 13px;">
        <td colspan="3" style="padding: 10px; text-align: left; border: 1.5px solid #2c3e50; color: #7f8c8d; font-weight: normal; font-size: 11px;">
          {{
            (() => {
              const d = $json.data;
              const t = d.length;
              const m = d.filter(i => (i.origen || i.output?.origen || '').includes('Manual')).length;
              const a = d.filter(i => (i.origen || i.output?.origen || '').includes('Artificial') || (i.origen || i.output?.origen || '').includes('IA')).length;
              const r = d.filter(i => (i.origen || i.output?.origen || '').includes('Directa')).length;
              return `<b>TOTAL FACTURA:</b> <span style="margin-left:10px;">(${t} prod: ${m} manual, ${a} AI, ${r} directa)</span>`;
            })()
          }}
        </td>
        <td style="padding: 10px; text-align: right; color: #e74c3c; border: 1.5px solid #2c3e50; font-size: 14px; background-color: #fff9f9;">
          $ {{ $json.data.reduce((sum, i) => sum + Number(i.valor_categoria || i.output?.valor_categoria || 0), 0).toLocaleString() }}
        </td>
        <td style="border: 1.5px solid #2c3e50;"></td>
      </tr>
    </tfoot>
  </table>
</div>

