// 1. Traer los datos directamente de los nodos originales de Supabase
const listaCategorias = $("Obtener_categorias").all();
const listaPagos = $("Obtener_metodos").all();

return items.map(item => {
  // Detectar si los datos vienen dentro de 'output' o en la raíz
  const factura = item.json.output || item.json;

  // FUNCIÓN DE BÚSQUEDA ULTRA-FLEXIBLE
  const buscarEnLista = (lista, nombreBuscado) => {
    if (!nombreBuscado) return null;

    // Función interna para "limpiar" el texto al extremo
    const limpiar = (t) => t.toString().toLowerCase()
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Quita tildes
      .replace(/\s+/g, "") // Quita TODOS los espacios
      .replace(/[^a-z0-9]/g, "") // Quita puntos, comas, guiones
      .replace(/de/g, ""); // Quita el conector "de" para evitar errores en "Tarjeta de Crédito"

    const buscado = limpiar(nombreBuscado);

    const encontrado = lista.find(elemento => {
      const nombreDB = limpiar(elemento.json.name || "");
      // Compara si uno contiene al otro después de la limpieza extrema
      return nombreDB === buscado || nombreDB.includes(buscado) || buscado.includes(nombreDB);
    });

    return encontrado ? encontrado.json.id : null;
  };

  // 2. Ejecutar las búsquedas
  const cId = buscarEnLista(listaCategorias, factura.categoria);
  const pId = buscarEnLista(listaPagos, factura.metodo_pago);

  // 3. Retornar el objeto plano (sin 'output') listo para Supabase
  return {
    json: {
      ...factura,
      category_id: cId,
      payment_method_id: pId,
      // Metadatos para verificar en el editor
      debug_info: {
        busco_pago: factura.metodo_pago,
        busco_cat: factura.categoria,
        encontro_pago: pId !== null,
        total_referencias_pago: listaPagos.length
      }
    }
  };
});

// Traemos TODOS los registros originales del XML
const originales = $("ProcesadorXML").all().map(o => o.json);

return items.map((item) => {

  // Datos que vienen de la IA (o del item si no hubo IA)
  const dataIA = item.json.output || item.json;

  // Buscamos el backup correcto por claves estables
  const backup = originales.find(o =>
    o.sessionId === dataIA.sessionId &&
    o.descripcion_detallada === dataIA.descripcion_detallada &&
    o.valor_categoria === dataIA.valor_categoria
  );

  // --- DETECCIÓN REAL DE IA ---
  const huboIA =
    !!item.json.output ||
    item.json.origen === "Inteligencia Artificial" ||
    backup?.necesita_ia === true ||
    backup?.necesita_ia === "true";

  // --- ERROR DE IA ---
  const esErrorIA =
    !!item.json.error ||
    (!dataIA.categoria && huboIA);

  // --- PRIORIDAD DE CATEGORÍA ---
  const categoriaFinal =
    (dataIA.categoria && !["Otros", "Sin Categoría"].includes(dataIA.categoria))
      ? dataIA.categoria
      : (backup?.categoria || "Otros");

  // --- CERTEZA ---
  let certezaFinal = parseInt(dataIA.certeza || backup?.certeza || 100);

  // --- ORIGEN ---
  let origenFinal = "Directa (XML)";

  if (huboIA) {
    if (esErrorIA) {
      origenFinal = "Manual (Fallo Técnico IA)";
      certezaFinal = 0;
    } else if (certezaFinal < 90) {
      origenFinal = "Manual (Poca Certeza IA)";
    } else if (
      backup &&
      dataIA.categoria &&
      dataIA.categoria !== backup.categoria
    ) {
      origenFinal = "Inteligencia Artificial (Corrección)";
    } else {
      origenFinal = "Inteligencia Artificial";
    }
  }

  return {
    json: {
      sessionId: backup?.sessionId || dataIA.sessionId || "N/A",
      fecha: backup?.fecha || dataIA.fecha || "N/A",
      tienda: backup?.tienda || dataIA.tienda || "N/A",
      descripcion_detallada:
        backup?.descripcion_detallada || dataIA.descripcion_detallada || "",
      productos: dataIA.productos || backup?.productos || "Sin nombre",
      valor_categoria: Number(backup?.valor_categoria || dataIA.valor_categoria || 0),
      metodo_pago: backup?.metodo_pago || dataIA.metodo_pago || "No especificado",
      categoria: categoriaFinal,
      certeza: certezaFinal,
      origen: origenFinal,
      razonamiento:
        dataIA.razonamiento ||
        backup?.razonamiento ||
        "Procesado correctamente.",
      // 🔐 fuente única de verdad
      necesita_ia: huboIA
    }
  };
});

// =====================================================
// 0. Extraer Datos de Entrada e ID
// =====================================================
const sessionId = $json["ext:UBLExtensions"]?.["ext:UBLExtension"]?.["ext:ExtensionContent"]?.["ds:Signature"]?.["Id"] 
                 || $execution.id 
                 || "sin_id";

const rawXml = $json.AttachedDocument?.["cac:Attachment"]?.["cac:ExternalReference"]?.["cbc:Description"];

if (!rawXml) {
  throw new Error("XML no encontrado en el JSON de entrada");
}

// =====================================================
// 1. Datos generales
// =====================================================
const fecha = rawXml.match(/<cbc:IssueDate>(.*?)<\/cbc:IssueDate>/)?.[1] || "Sin_Fecha";
const nombreTiendaRaw = rawXml.match(/<cac:AccountingSupplierParty>[\s\S]*?<cbc:Name>(.*?)<\/cbc:Name>/)?.[1] || "Comercio_Desconocido";

const tienda = nombreTiendaRaw
  .trim()
  .replace(/\s+/g, "_")
  .split("_")
  .slice(0, 2)
  .join("_");

const paymentCode = rawXml.match(/<cbc:PaymentMeansCode>(.*?)<\/cbc:PaymentMeansCode>/)?.[1] || "1";

let metodoPago = "Efectivo";
if (paymentCode === "48" || paymentCode === "49") metodoPago = "Tarjeta Crédito";

// =====================================================
// 2. Diccionario Maestro de Categorías
// =====================================================
const normalizar = (txt) => txt.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const categorias = {
  "Alimentación": ["manzana","cebolla","papa","aguacate","limon","banano","tomate","queso","leche","arroz","huevo","carne","pollo","veg","burguer","fruta","verdura","hortaliza","chonto"],
  "Arriendo y mudanzas": ["arriendo", "mudanza", "trasteo", "deposito"],
  "Aseo y limpieza": ["papel", "cepillo", "seda dental", "crema", "detergente", "jabon", "limpiador", "cloro", "lavaloza"],
  "Cuidado personal y estética": ["barberia", "peluqueria", "tatuaje", "corte", "cabello", "estetica", "shampoo"],
  "Teléfono": ["recarga", "saldo", "datos", "tigo", "claro", "movistar"],
  "Restaurantes": ["coraje", "oh food", "vegan", "veggie", "tulia", "restaurante", "almuerzo", "cena"],
  "Mecato y bebidas": ["panaderia", "cerveza", "alcohol", "snack", "mecato", "gaseosa", "jugo", "licor", "galleta", "vino"],
  "Educación": ["matricula", "pension escolar", "curso", "diplomado"],
  "Gym": ["smartfit", "gimnasio", "entrenamiento", "proteina"],
  "Oficina y trabajo": ["coworking", "escritorio", "we work"],
  "Salidas, hospedajes y ocio": ["entrada", "airbnb", "hotel", "parque", "cine", "concierto"],
  "Aplicativos, libros y gadgets": ["netflix", "spotify", "google storage", "almacenamiento", "icloud", "kindle"],
  "Ropa, calzado y accesorios": ["aretes", "correa", "camisa", "pantalon", "medias", "ropa interior", "zapatos", "tenis"],
  "Farmacia y Salud": ["pastilla", "condon", "drogueria", "medicamento", "jarabe"],
  "Salud y pensión": ["salud", "pension", "eps", "arl"],
  "Seguro de vida": ["sura", "seguro vida"],
  "Seguro moto": ["seguro vehiculo", "soat"],
  "Civica": ["recarga civica", "transporte", "metro"],
  "Transporte": ["uber", "avianca", "latam", "taxi", "cabify", "pasaje"],
  "Gasolina": ["primax", "terpel", "combustible", "estacion de servicio"],
  "Parqueadero": ["parqueadero", "estacionamiento"],
  "Moto": ["revision", "aceite moto", "taller"],
  "Regalos": ["flores", "chocolate", "regalo", "detalle"],
  "Utilería hogar y decoración": ["cocina", "decoracion", "sabana", "toalla", "utensilio"],
  "Utilería oficina": ["cuaderno", "lapicero", "resaltador", "papeleria"],
  "Documentos y papelería": ["certificado", "notaria", "tramite"],
  "Grandes activos": ["televisor", "moto", "carro", "casa", "nevera"],
  "Impuestos y multas": ["impuesto", "multa", "fotomulta"]
};

const clasificar = (nombre) => {
  const n = normalizar(nombre);
  for (const cat in categorias) {
    if (categorias[cat].some(p => n.includes(normalizar(p)))) return cat;
  }
  return "Otros";
};

// =====================================================
// 3. Procesar líneas
// =====================================================
const lineas = rawXml.match(/<cac:InvoiceLine>[\s\S]*?<\/cac:InvoiceLine>/g) || [];
const resumen = {};

lineas.forEach((linea) => {
  const nombre = linea.match(/<cbc:Description>(.*?)<\/cbc:Description>/)?.[1]?.trim();
  if (!nombre) return;
  const base = parseFloat(linea.match(/<cbc:LineExtensionAmount.*?>(.*?)<\/cbc:LineExtensionAmount>/)?.[1] || 0);
  const iva = parseFloat(linea.match(/<cac:TaxTotal>[\s\S]*?<cbc:TaxAmount.*?>(.*?)<\/cbc:TaxAmount>/)?.[1] || 0);
  const total = base + iva;
  const categoria = clasificar(nombre);

  if (!resumen[categoria]) {
    resumen[categoria] = { total: 0, items: [], items_detallados: [] };
  }
  resumen[categoria].total += total;
  resumen[categoria].items.push(nombre);
  resumen[categoria].items_detallados.push({ nombre, total: Math.round(total * 100) / 100 });
});

// =====================================================
// 4. Salida Final con Confianza Numérica
// =====================================================
const finalOutput = [];

Object.keys(resumen).forEach((categoria) => {
  const esDesconocido = (categoria === "Otros");

  if (esDesconocido) {
    resumen[categoria].items_detallados.forEach((prod) => {
      finalOutput.push({
        json: {
          sessionId, fecha, tienda,
          descripcion_detallada: `${tienda}_OTR`,
          categoria: "Otros",
          valor_categoria: prod.total,
          metodo_pago: metodoPago,
          productos: prod.nombre,
          certeza: 0, // Fuerza revisión manual
          necesita_ia: true,
          razonamiento: "Producto desconocido por el sistema"
        }
      });
    });
  } else {
    finalOutput.push({
      json: {
        sessionId, fecha, tienda,
        descripcion_detallada: `${tienda}_${categoria.substring(0,3).toUpperCase()}`,
        categoria,
        valor_categoria: Math.round(resumen[categoria].total * 100) / 100,
        metodo_pago: metodoPago,
        productos: resumen[categoria].items.join(", "),
        certeza: 100, // Detectado por diccionario, confianza total
        necesita_ia: false,
        razonamiento: "false"
      }
    });
  }
});

return finalOutput;
